import type { AppLocale } from "@gugu/localization";

import manifest from "../../assets/studio/manifest.json";

/**
 * REAL GuGu Studio CRM captures (business workspace, ?demo=1), regenerated by
 * `node scripts/capture-studio-screens.mjs <dev-server-url>`. Do not edit the images by hand.
 */
const SCREENS = {
  vi: {
    overview: require("../../assets/studio/vi/overview.webp") as number,
    timeline: require("../../assets/studio/vi/timeline.webp") as number,
    upcoming: require("../../assets/studio/vi/upcoming.webp") as number,
    kpis: require("../../assets/studio/vi/kpis.webp") as number,
    aiSetup: require("../../assets/studio/vi/ai-setup.webp") as number,
  },
  en: {
    overview: require("../../assets/studio/en/overview.webp") as number,
    timeline: require("../../assets/studio/en/timeline.webp") as number,
    upcoming: require("../../assets/studio/en/upcoming.webp") as number,
    kpis: require("../../assets/studio/en/kpis.webp") as number,
    aiSetup: require("../../assets/studio/en/ai-setup.webp") as number,
  },
} as const;

export type ScreenName = keyof (typeof SCREENS)["vi"];

/** Pixel sizes written by the capture script (per locale; crops differ slightly with text length). */
export const screenSize = (locale: AppLocale, name: ScreenName) => {
  const key = name === "aiSetup" ? "ai-setup" : name;
  return (
    (manifest as Record<AppLocale, Record<string, { w: number; h: number }>>)[locale][key] ?? {
      w: 16,
      h: 10,
    }
  );
};

export const screen = (locale: AppLocale, name: ScreenName) => SCREENS[locale][name];
